import type { Metadata } from 'next';

/**
 * Tab icons (generated by packages/app-icons). Stage and production share one build, so the
 * environment is read at request time: QA and dev get a violet corner dot, stage a pink one.
 * Returns the dot SVG for those, and null for production, which has no SVG (see appIcons).
 */
export function faviconSvgPath(env: string | undefined): string | null {
  switch ((env ?? '').toLowerCase()) {
    case 'qa':
    case 'development':
    case 'preview':
      return '/favicon-qa.svg';
    case 'stage':
    case 'staging':
      return '/favicon-stage.svg';
    default:
      return null;
  }
}

/** Exact-size PNGs (each its own downscale of the owner's art), so the browser never shrinks the art. */
export const TAB_PNG_SIZES = [16, 32, 48, 96] as const;

/**
 * Production: the ICO and the sized PNGs, with no SVG, because a browser would prefer the SVG and
 * blur it. QA and stage: the ICO and the dot SVG, which the browser prefers, so the dot shows.
 */
export function appIcons(env: string | undefined): NonNullable<Metadata['icons']> {
  const svg = faviconSvgPath(env);
  return {
    icon: [
      { url: '/favicon.ico', sizes: '16x16 32x32 48x48' },
      ...(svg
        ? [{ url: svg, type: 'image/svg+xml' }]
        : TAB_PNG_SIZES.map((s) => ({ url: `/favicon-${s}x${s}.png`, type: 'image/png', sizes: `${s}x${s}` }))),
    ],
    apple: '/apple-touch-icon.png',
  };
}
